L["event.alterac_dawn_trout.name"] = "Dawn Trout"
L["event.alterac_dawn_trout.note"] = "Cold lakes high among the peaks. The wager is trout before breakfast, and the frost on the line comes free."
L["event.azshara_lobster.name"] = "Lobster by Lamplight"
L["event.azshara_lobster.note"] = "A broken coast of fallen stone and faded grandeur. The lobster keep close to the rocks, and the yellowtail keep their distance."
L["event.barrens_oddities.name"] = "Oddity at Dusk"
L["event.barrens_oddities.note"] = "The pools of the dry plains turn out some strange fish. Look them over at sundown, and think twice before cooking any."
L["event.burning_steppes_salmon.name"] = "Salmon under Ash"
L["event.burning_steppes_salmon.note"] = "Black hills, ash on the water and salmon under it. Bring a hat with a wide brim."
L["event.darkshore_moonlight.name"] = "Grouper by Moonlight"
L["event.darkshore_moonlight.note"] = "A long grey coast under old, dark trees. The wager is grouper once the moon is up, and the nights there are long."
L["event.deadwind_pass_night.name"] = "Cold Pass, Long Night"
L["event.deadwind_pass_night.note"] = "A cold pass where nothing grows, and an old tower keeping watch over the road. The salmon pay it no attention."
L["event.duskwood_witching.name"] = "Witching Hour"
L["event.duskwood_witching.note"] = "Slow black rivers through woods where it never quite gets light. After midnight the fish bite, and so does everything else."
L["event.dustwallow_marsh_night.name"] = "Late on the Marsh"
L["event.dustwallow_marsh_night.note"] = "A warm, wet coast that hums all night. Trout in the creeks, yellowtail off the shore, and something always biting your neck."
L["event.eastern_plaguelands_night.name"] = "Midnight in the Dead East"
L["event.eastern_plaguelands_night.note"] = "Nobody fishes the dead east after dark if they can help it. The salmon have come to count on that."
L["event.eastern_plaguelands_redgill.name"] = "Grim Lakes of the East"
L["event.eastern_plaguelands_redgill.note"] = "Grim to look at and generous underneath, like most good lakes and some old anglers."
L["event.felwood_moonglade.name"] = "Tainted Woods, Clear Lake"
L["event.felwood_moonglade.note"] = "Sickly streams under the tainted trees, and a clear, quiet lake beyond them. The redgill don't seem to notice the difference."
L["event.feralas_redgill.name"] = "Redgill in the Rain"
L["event.feralas_redgill.note"] = "Redgill up the rivers, yellowtail off the coast, and rain over both. The forest never quite dries."
L["event.hinterlands_coast.name"] = "Where the Hills Meet the Sea"
L["event.hinterlands_coast.note"] = "Wild hill country, gryphons overhead, and a quiet sea at the bottom of it all. The mightfish are worth the climb down."
L["event.hinterlands_redgill.name"] = "Cold Rivers, Late Nights"
L["event.hinterlands_redgill.note"] = "Clear, cold rivers through the wild hills. The redgill keep late hours, so bring a second blanket."
L["event.loch_modan_frenzy.name"] = "Frenzy Water"
L["event.loch_modan_frenzy.note"] = "A wide, cold lake in dwarf country, where the fish fight above their size. Now and then something finer comes up with them."
L["event.silithus_coast.name"] = "Sand to the Water's Edge"
L["event.silithus_coast.note"] = "Sand all the way down to the water, and something buzzing in the dunes behind. Past the surf it's honest sea fish."
L["event.silithus_salmon.name"] = "Salmon in the Sand"
L["event.silithus_salmon.note"] = "Whitescale this far south is a surprise to everyone, the salmon included. Take them while the light lasts."
L["event.stranglethorn_coast.name"] = "Jungle Shore"
L["event.stranglethorn_coast.note"] = "Warm water, long beaches and a cod under every rock. Keep one eye on the treeline."
L["event.tanaris_yellowtail.name"] = "Noon on the Desert Coast"
L["event.tanaris_yellowtail.note"] = "Sand to the tideline and not a scrap of shade. The yellowtail don't mind the heat; the angler might."
L["event.tirisfal_silverpine_dusk.name"] = "Grey Waters at Dusk"
L["event.tirisfal_silverpine_dusk.note"] = "Cold water under grey northern woods, quiet as a churchyard. Nobody here is in a hurry, least of all the fish."
L["event.ungoro_redgill.name"] = "Dusk in the Crater"
L["event.ungoro_redgill.note"] = "Steaming pools at the bottom of the crater, thick with redgill. Something larger is always watching from the ferns."
L["event.western_plaguelands_lake.name"] = "An Afternoon in the Blight"
L["event.western_plaguelands_lake.note"] = "Dead fields, a sick sky and a lake full of healthy redgill. Nobody has told them about the plague."
L["event.winterspring_daylight.name"] = "Short Days in the Snow"
L["event.winterspring_daylight.note"] = "Up in the snow the days are short and the lakes are cold. Spend the light on the water, and the dark by a fire."
L["event.winterspring_salmon.name"] = "Snowbound Salmon"
L["event.winterspring_salmon.note"] = "Cold water, white salmon and the evenings drawing in early. Mind the ice on the way home."
